            gpuListJoined += gpuName;

            gpuBlocks += "\n    " + gpuName + "\n";
            gpuBlocks += "      Power Cap ServiceName : " + gi.serviceName +
                         "\n";
            gpuBlocks += "      Power Cap ObjectPath  : " + gi.objectPath +
